from pathlib import Path
import json,hashlib,xml.etree.ElementTree as ET
b=Path(__file__).resolve().parent.parent
root=b.parents[3]
journey=b/'QA/Verify05/Candidate/Journey'
rows=[]
for n in range(11,21):
 w=[json.loads((journey/f'Round{n}_Attempt{a}_Witness.json').read_text()) for a in range(1,4)]
 rows.append({'round':n,'moveLimit':w[0]['moveLimit'],'solutionMoves':[x['moves'] for x in w],'attempts':[1,2,3],'initialHashes':[x['initialHash'] for x in w],'finalHashes':[x['finalHash'] for x in w]})
(b/'QA/BalanceScreening.json').write_text(json.dumps({'method':'Bounded deterministic beam search, width8, fewer than14000 expanded actions per seed, no inventory. Each witness replayed against expected plan and final hashes. Not a human win-rate estimate.','rows':rows},indent=2))
results={}
for run,suite in [('Verify05','Candidate'),('Verify04','EditMode'),('Verify04','Campaign')]:
 a=ET.parse(b/f'QA/{run}/{suite}/results.xml').getroot().attrib
 results[suite]={'run':run,**{k:a[k] for k in ['result','total','passed','failed','skipped','duration']}}
(b/'QA/Verification.json').write_text(json.dumps({'unity':'6000.5.9f1','results':results,'distinctPassed':sum(int(a['passed']) for a in results.values()),'process':'Prior approved verification-only Vulkan, descriptor limit4096, isolated configs; project settings unchanged.','coverage':['20rounds x3attempt seeds deterministic legal nonmatching starts','30 inventory-free completion traces with replay plan/final hashes','Authored line/Burst opportunities across3seeds','Candidate and legacy story boundaries and preserved legacy boards/rewards','Round10 result acknowledgement selects11 then exposes hearth without extra reward','Actual round11 UI win and Continue to12','Current campaign regression suites'],'limits':['No human difficulty acceptance','No physical Android run','No full repository suite','UI later-round/story captures use declared test progress; only round11 completion is executed on the animated Unity board'],'earlierRuns':{'Verify01':'Compilation: wrong progress and snapshot member names in new tests; corrected.','Verify02':'11/14 passed. Authored line opportunity could become a different special; added neighbor guards. Two fixture failures imported >10 rounds through legacy codec; replaced with campaign transactions. All30 solver witnesses existed in this initial run.','Verify03':'14/14 passed. Followed by stronger round10 acknowledgement test and new explicit jump menu; final Verify05 passed.'}},indent=2))
assets=root/'Assets/LegendsOfRus/EditorContent/CampaignCandidates/Chapter01Sector01'
(b/'QA/CandidateHashes.json').write_text(json.dumps({str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest() for p in assets.glob('*.json')},indent=2))
items=[('Sector_Round15','Round 15 · two-stage ice basin'),('Sector_Round20','Round 20 · ice and chains'),('Sector_Round11','Round 11 · recovery board'),('Sector_Round18','Round 18 · T-match beside crates'),('Sector_Round11_Victory','Round 11 · actual board victory'),('Sector_Story10_EN','Hearth restored · English'),('Sector_Story10_RU','Hearth restored · Russian'),('Sector_Story20_EN','Well cleared · English'),('Sector_Story20_RU','Well cleared · Russian')]
records=[]
for key,label in items:
 path=f'QA/Verify05/Candidate/Journey/CampaignUI_{key}.png';assert (b/path).exists()
 records.append([path,label+' — actual Unity render. Development fixture progress; no live save.'])
options=''.join(f'<option value="{i}">{label}</option>' for i,(_,label) in enumerate(items))
table=''.join(f'<tr><td>{r["round"]}</td><td>{r["moveLimit"]}</td><td>{" / ".join(map(str,r["solutionMoves"]))}</td></tr>' for r in rows)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Campaign R9 — hearth to well</title><style>*{box-sizing:border-box}body{margin:0;background:#0b1520;color:#efdfc2;font:16px/1.5 system-ui}main{max-width:1050px;margin:auto;padding:22px}h1,h2{color:#dfb563;line-height:1.2}.layout{display:grid;grid-template-columns:minmax(280px,420px) 1fr;gap:24px}section{background:#142331;border:1px solid #685735;padding:16px;border-radius:8px;margin-bottom:16px}img{display:block;width:100%;height:auto}select{width:100%;font:inherit;background:#243c4f;color:#f2e6ce;padding:10px}a{color:#a8d8fa}small{display:block;margin:12px 0}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:6px;border-bottom:1px solid #425064}@media(max-width:700px){.layout{grid-template-columns:1fr}main{padding:12px}}</style><main><p>Campaign Foundation · R9 · Playable candidate</p><h1>From the restored hearth to the village well.</h1><p>Ten authored rounds, three added story beats, existing artwork and current matching rules. Further animation and effect work remains deferred.</p><div class="layout"><section><label for="capture">Actual Unity capture</label><select id="capture">OPTIONS</select><small id="caption"></small><a id="full" target="_blank" rel="noopener"><img id="screen" alt="Actual Unity campaign candidate capture"></a></section><div><section><h2>Play the new batch</h2><p>In Play Mode, reach Home. Select <strong>Legends of Rus → Development → Campaign Sector Candidate - Start at 11 (Test Progress)</strong>.</p><p>The shortcut seeds disposable progress through10 and starts with the new hearth scene. For a fresh run from1, select <strong>Campaign Sector 01 Candidate (Rounds 1-20)</strong>.</p><p>Both are in-memory previews. Leaving Play Mode resets them. Production content and the live player save remain unchanged.</p></section><section><h2>Connected story</h2><p>After2: an apple blossom. After10: one hearth secured, not chapter completion. After20: the well is clear; the granary is next.</p><p>Legacy boards1–10 and rewards are preserved. The original ten-round finale remains in the legacy package. Round21 and Chapter2 stay unavailable.</p></section><section><h2>Automated screening</h2><p>133 distinct Unity checks passed. All20 starts checked across3attempt seeds. All30 new-round completion traces use no inventory and replay to verified hashes.</p><table><thead><tr><th>Round</th><th>Budget</th><th>Solution moves<br>attempt1 /2 /3</th></tr></thead><tbody>TABLE</tbody></table><p>These short solutions come from a search with full board/refill knowledge. They establish completion paths, not player difficulty or win rates. Human testing is the next step before tuning budgets or extending21–30.</p></section><section><h2>Review evidence</h2><p><a href="StoryAndContent.md">Story decisions and playtest instructions</a><br><a href="ImplementationReport.md">Implementation report</a><br><a href="QA/Verification.json">Unity verification</a> · <a href="QA/BalanceScreening.json">Completion screening</a> · <a href="QA/Scope.json">Changed files</a></p><p>Story/later-board captures use test progress. Round11 victory was executed through the actual Unity board. No Android performance or human acceptance claim.</p></section></div></div></main><script>const items=RECORDS;const select=document.querySelector('#capture');function show(){let i=items[+select.value];document.querySelector('#screen').src=i[0];document.querySelector('#full').href=i[0];document.querySelector('#caption').textContent=i[1]}select.onchange=show;show();</script></html>'''
(b/'Campaign_Foundation_R9_Review.html').write_text(html.replace('OPTIONS',options).replace('TABLE',table).replace('RECORDS',json.dumps(records)))
p=b/'Sources/CheckReview.cjs';p.write_text(p.read_text().replace('i<8','i<9'))
print(results)
